//! Identifier types. Types with a validity rule keep their field private.

use std::borrow::Borrow;
use std::fmt;

use serde::{Serialize, Serializer};

const FIFO_SUFFIX: &str = ".fifo";

fn is_id_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_' || b == b'-'
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MessageId(u64);

impl MessageId {
    pub fn new(n: u64) -> Self {
        Self(n)
    }
}

impl fmt::Display for MessageId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "m-{}", self.0)
    }
}

impl Serialize for MessageId {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.collect_str(self)
    }
}

/// A delivery's handle: `r-<n>` with `n` counting deliveries from 1.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ReceiptHandle(u64);

impl ReceiptHandle {
    pub fn new(n: u64) -> Self {
        Self(n)
    }

    /// Accepts only the exact text of a handle among the first `issued` ones.
    pub fn parse(text: &str, issued: u64) -> Option<Self> {
        let digits = text.strip_prefix("r-")?;
        if digits.starts_with('0') || !digits.bytes().all(|b| b.is_ascii_digit()) {
            return None;
        }
        digits.parse().ok().filter(|n| (1..=issued).contains(n)).map(Self)
    }
}

impl fmt::Display for ReceiptHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "r-{}", self.0)
    }
}

impl Serialize for ReceiptHandle {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.collect_str(self)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize)]
pub struct QueueName(String);

impl QueueName {
    /// Returns `None` when `text` breaks the name syntax.
    pub fn parse(text: &str) -> Option<Self> {
        let base = text.strip_suffix(FIFO_SUFFIX).unwrap_or(text);
        let max = if base.len() == text.len() { 80 } else { 75 };
        let valid = (1..=max).contains(&base.len()) && base.bytes().all(is_id_byte);
        valid.then(|| Self(text.to_owned()))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }

    pub fn has_fifo_suffix(&self) -> bool {
        self.0.ends_with(FIFO_SUFFIX)
    }
}

impl Borrow<str> for QueueName {
    fn borrow(&self) -> &str {
        &self.0
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize)]
pub struct GroupId(String);

impl GroupId {
    pub fn parse(text: &str) -> Option<Self> {
        is_wire_id(text).then(|| Self(text.to_owned()))
    }
}

/// A FIFO deduplication id. Content-based ids are the body, so any text is allowed there.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct DedupId(String);

impl DedupId {
    pub fn parse(text: &str) -> Option<Self> {
        is_wire_id(text).then(|| Self(text.to_owned()))
    }

    pub fn from_body(body: &str) -> Self {
        Self(body.to_owned())
    }
}

fn is_wire_id(text: &str) -> bool {
    (1..=128).contains(&text.len()) && text.bytes().all(is_id_byte)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn queue_name_syntax() {
        let long = "a".repeat(80);
        let long_fifo = format!("{}.fifo", "a".repeat(75));
        let too_long_fifo = format!("{}.fifo", "a".repeat(76));
        let cases = [
            ("jobs", true),
            ("a-B_9", true),
            ("a.fifo", true),
            (long.as_str(), true),
            (long_fifo.as_str(), true),
            (too_long_fifo.as_str(), false),
            ("", false),
            (".fifo", false),
            ("a.b", false),
            ("a.fifo.fifo", false),
            ("jobs ", false),
            ("jöbs", false),
        ];
        for (name, valid) in cases {
            assert_eq!(QueueName::parse(name).is_some(), valid, "{name:?}");
        }
    }

    #[test]
    fn receipt_handles_are_compared_as_exact_text() {
        let cases = [
            ("r-1", Some(1)),
            ("r-3", Some(3)),
            ("r-4", None),
            ("r-0", None),
            ("r-01", None),
            ("R-1", None),
            ("r-1 ", None),
            ("r-+1", None),
        ];
        for (text, n) in cases {
            assert_eq!(ReceiptHandle::parse(text, 3), n.map(ReceiptHandle::new), "{text:?}");
        }
    }
}
